(()=>{'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const c=window.D3_RECENT.cases.find(x=>x.id===document.body.dataset.recentCase),url=p=>'../'+p;
document.documentElement.style.setProperty('--case',c.color);
const sections=[['brief','工程题目'],['difficulty','核心难点'],['inputs','给模型的素材'],['deliverables','交付与验收缺口'],['results','交付可视化'],['environment','软件与运行'],['evidence','题目与证据下载']];
const label=(n,t,en)=>`<div class="section-label"><span>${n}</span><h2>${t}</h2><small>${en}</small></div>`;
const table=(head,rows)=>`<div class="table-wrap"><table><thead><tr>${head.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
document.querySelector('#recent-detail').innerHTML=`
 <div class="project-context wrap recent-crumb"><a href="../../">SimulationLE/Engineer</a><span>/</span><a href="../">D3 改编与原创</a><span>/</span><b>CASE ${c.number}</b></div>
 <section class="recent-hero wrap"><div><p class="eyebrow">RETAINED ENGINEERING CASE / ${c.number}</p><div class="tag-row"><span class="tag">${esc(c.domain)}</span><span class="tag">题目已保留 · 参考解空缺</span></div><h1>${esc(c.short)}<span>${esc(c.title)}</span></h1><p class="recent-lead">${esc(c.summary)}</p><div class="recent-actions"><a class="primary-link" href="#brief">阅读工程题目 ↓</a><a class="doc-button" href="#results">查看模型交付 ↗</a><a class="doc-button" href="${url(c.docs.task)}" download>下载冻结题面 ↓</a></div></div><figure class="recent-hero-image"><img src="${url(c.heroImage)}" alt="${esc(c.visuals[0].title)}"><figcaption>模型实际交付图 · ${esc(c.visuals[0].caption)}</figcaption></figure></section>
 <div class="wrap"><div class="result-banner recent-verdict"><div><strong>unresolved · 尚未达到工程验收要求</strong><p>${esc(c.outcomeText)}</p></div><span class="pill">${esc(c.scoreNote)}</span></div></div>
 <div class="recent-layout wrap"><aside class="recent-sidebar"><p class="eyebrow">CASE EVIDENCE</p><nav aria-label="案例章节">${sections.map(([id,title],i)=>`<a href="#${id}"><span>${String(i+1).padStart(2,'0')}</span>${title}</a>`).join('')}</nav><a class="recent-sibling" href="../${c.id==='oc6'?'rotor67':'oc6'}/">另一个保留案例 ↗<br><strong>${c.id==='oc6'?'NASA Rotor 67':'OC6 半潜式平台'}</strong></a></aside><div class="recent-body">
 <section class="content-section" id="brief">${label('01','工程题目','THE ENGINEERING BRIEF')}<p class="section-lead">${esc(c.scenario)}</p><div class="spec-grid">${c.specs.map(([v,k])=>`<div><strong>${esc(v)}</strong><small>${esc(k)}</small></div>`).join('')}</div><ol class="task-list">${c.task.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><div class="formula">${esc(c.formula)}</div><p class="recent-scope">上述阈值为本题原创工程合同，不是数据发布机构的官方认证要求。完整定义以冻结题面与协议为准。</p></section>
 <section class="content-section" id="difficulty">${label('02','真正困难的工程问题','WHY THIS IS HARD')}<div class="difficulty-grid">${c.difficulties.map((d,i)=>`<div class="difficulty"><span class="step">CHALLENGE / 0${i+1}</span><h3>${esc(d.name)}</h3><p>${esc(d.text)}</p></div>`).join('')}</div></section>
 <section class="content-section" id="inputs">${label('03','给模型的素材','INPUT ASSETS')}${table(['素材','来源性质','提供内容','文件形态'],c.assets.map(a=>[a.name,a.kind,a.description,a.format]))}<div class="evidence-note"><span>ⓘ</span><div>${esc(c.inputNote)}</div></div><div class="link-row">${[['sources','来源与许可'],['audit','输入数据审计'],['protocol','验证协议']].map(([key,name])=>`<a class="doc-button" href="${url(c.docs[key])}" download>${name} ↓</a>`).join('')}</div></section>
 <section class="content-section" id="deliverables">${label('04','预期、实际交付与验收缺口','DELIVERABLES & ACCEPTANCE')}${table(['交付项','题目希望模型完成','模型实际完成'],c.deliveries.map(d=>[d.name,d.expected,d.actual]))}<h3 class="gate-title">尚未满足哪些工程验收要求？</h3><div class="gate-list">${c.gates.map(([title,status,expected,actual],i)=>`<article class="gate-item"><div><span class="gate-index">${String(i+1).padStart(2,'0')}</span><h4>${esc(title)}</h4><span class="state missing">${esc(status)}</span></div><p><b>验收要求</b>${esc(expected)}</p><p><b>本轮证据</b>${esc(actual)}</p></article>`).join('')}</div></section>
 <section class="content-section" id="results">${label('05','模型交付 · 可视化证据','WHAT THE AGENT DELIVERED')}<div class="metric-grid">${c.results.map(([v,k])=>`<div class="metric"><strong>${esc(v)}</strong><small>${esc(k)}</small></div>`).join('')}</div><div class="evidence-note"><span>ⓘ</span><div>${esc(c.resultNote)}</div></div><div id="recent-evidence"></div></section>
 <section class="content-section" id="environment">${label('06','专业软件与实际运行边界','THE ENGINEERING TOOLCHAIN')}${table(['环境 / 软件','版本','用途与限制','状态'],c.environment.map(s=>[s.name,s.version,s.use,s.status]))}<p class="environment-footer">${esc(c.runSummary)}</p><div class="evidence-note"><span>ⓘ</span><div>${esc(c.caveat)}</div></div></section>
 <section class="content-section" id="evidence">${label('07','题目、原报告与证据下载','FILES & PROVENANCE')}<div class="recent-download-grid">${c.downloads.map(([path,title])=>`<a href="${url(path)}" download><span>↓</span><div><strong>${esc(title)}</strong><small>${esc(path.split('/').pop())}</small></div></a>`).join('')}</div><h3>原始研究与素材来源</h3><ul class="recent-sources">${c.sources.map(([href,title])=>`<li><a href="${href}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a></li>`).join('')}</ul><p class="recent-scope">完整冻结输入、CAD、大型原始场与运行历史继续保留在研究服务器。网页提供经选取的题面、模型原图和核验材料；每个文件可在<a href="../evidence/recent-evidence-manifest.json">来源与SHA-256清单</a>中追溯。${esc(c.reference)}。</p></section>
 </div></div>`;
window.mountRecentEvidence(document.querySelector('#recent-evidence'),c,'../');
const dialog=document.querySelector('#image-dialog');document.querySelector('#close-image').onclick=()=>dialog.close();
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
const observer=new IntersectionObserver(entries=>{const e=entries.filter(e=>e.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top)[0];if(e)document.querySelectorAll('.recent-sidebar nav a').forEach(a=>{const on=a.hash==='#'+e.target.id;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});},{rootMargin:'-95px 0px -60% 0px'});
document.querySelectorAll('.content-section').forEach(s=>observer.observe(s));
if(location.hash)requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView({behavior:'instant'}));
})();
